using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using g3;
using Xunit;

namespace geometry3Sharp.Tests
{
    /// <summary>
    /// The predicates generated by tools/PredicateCompiler (experiment, docs/design/PREDICATE_COMPILER.md): the
    /// generated file is up to date, and every stage gives the sign of the exact determinant (the hand-written
    /// BigInteger evaluation of ExactPredicates is the oracle), also where the error bounds are tight: nearly and
    /// exactly degenerate inputs, inexact differences, products in the subnormal range, inputs out of the
    /// expansion range.
    /// </summary>
    public class GeneratedPredicatesTests
    {
#if NET
        [Fact]
        public void GeneratedFile_IsUpToDate()
        {
            string dir = Path.Combine(AppContext.BaseDirectory, "PredicateCompiler");
            string spec = File.ReadAllText(Path.Combine(dir, "predicates.spec"));
            string expected = File.ReadAllText(Path.Combine(dir, "GeneratedPredicates.cs.txt")).Replace("\r\n", "\n");
            string generated = G3PredicateCompiler.PredicateCompiler.Compile(spec);
            Assert.True(expected == generated, "math/Generated/GeneratedPredicates.cs is out of date: regenerate it (tools/PredicateCompiler/README.md)");
        }

        static System.Numerics.BigInteger Pow2(int e) => System.Numerics.BigInteger.Pow(2, e);

        // value >= k u^j / (1 - u)^n, exactly (u = 2^-53)
        static bool atLeast(double value, int k, int j, int n)
        {
            long bits = BitConverter.DoubleToInt64Bits(value);
            int e = (int)((bits >> 52) & 0x7FF) - 1075;
            var m = new System.Numerics.BigInteger((bits & 0xFFFFFFFFFFFFFL) | (1L << 52));
            // m 2^e (2^53 - 1)^n >= k 2^(53 n - 53 j)
            var lhs = m * System.Numerics.BigInteger.Pow(Pow2(53) - 1, n);
            var rhs = k * Pow2(53 * n - 53 * j);
            return e >= 0 ? lhs * Pow2(e) >= rhs : lhs >= rhs * Pow2(-e);
        }

        /// <summary>
        /// the stage B and C constants against an independent derivation: leading terms 2 u / 4 u and 7 u^2 / 42 u^2,
        /// and the depth of the permanent's roundings (orient2d 2; incircle 7: the roundings of the factors of a product add)
        /// </summary>
        [Fact]
        public void StageConstants_CoverTheRoundingsOfThePermanent()
        {
            string code = File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "PredicateCompiler", "GeneratedPredicates.cs.txt"));
            var b = System.Text.RegularExpressions.Regex.Matches(code, @"boundB = ([0-9.e-]+) \*").Select(x => double.Parse(x.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture)).ToArray();
            var c = System.Text.RegularExpressions.Regex.Matches(code, @"boundC = ([0-9.e-]+) \*").Select(x => double.Parse(x.Groups[1].Value, System.Globalization.CultureInfo.InvariantCulture)).ToArray();
            Assert.True(atLeast(b[0], 2, 1, 3), "orient2d stage B");
            Assert.True(atLeast(c[0], 7, 2, 3), "orient2d stage C");
            Assert.True(atLeast(b[1], 4, 1, 8), "incircle stage B");
            Assert.True(atLeast(c[1], 42, 2, 8), "incircle stage C");
        }

        [Theory]
        [InlineData("predicate P(a, b, c, d)\n x = a - b\n sign x * c - d", "homogeneous")]
        [InlineData("predicate P(a, b, c, d)\n sign a * b - c * d", "difference")]
        [InlineData("predicate P(c, b, e, d)\n sign (c - b) * (e - d) - (b - c) * (d - e)", "clashes")]
        [InlineData("predicate P(a, v12, e, d)\n sign (a - v12) * (e - d) - (e - a) * (d - e)", "clashes")]
        [InlineData("predicate P(a, b)\n x = a - b\n y = x * x * x * x\n sign y * x * x * x - x * x * y * x", "degree")]
        public void Compiler_RejectsUnsupportedFormulas(string spec, string reason)
        {
            var ex = Assert.Throws<NotSupportedException>(() => G3PredicateCompiler.PredicateCompiler.Compile(spec));
            Assert.Contains(reason, ex.Message);
        }
#endif

        // --- oracles (hand-written, independent of the generator)

        static int orient2d_ref(double[] p) =>
            ExactPredicates.orient2d_bigint(new Vector2d(p[0], p[1]), new Vector2d(p[2], p[3]), new Vector2d(p[4], p[5]));

        static int incircle_ref(double[] p) =>
            ExactPredicates.incircle_bigint(new Vector2d(p[0], p[1]), new Vector2d(p[2], p[3]), new Vector2d(p[4], p[5]), new Vector2d(p[6], p[7]));

        static int orient2d(double[] p) => GeneratedPredicates.Orient2d(p[0], p[1], p[2], p[3], p[4], p[5]);
        static int incircle(double[] p) => GeneratedPredicates.InCircle(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7]);

        // --- inputs

        // the next / previous double (Math.BitIncrement / BitDecrement are not in .NET Framework)
        static double next(double x)
        {
            if (x == 0) return double.Epsilon;
            long bits = BitConverter.DoubleToInt64Bits(x);
            return BitConverter.Int64BitsToDouble(x > 0 ? bits + 1 : bits - 1);
        }
        static double prev(double x) => -next(-x);

        static double ulps(double x, int k)
        {
            for (; k > 0; --k) x = next(x);
            for (; k < 0; ++k) x = prev(x);
            return x;
        }

        static double[] perturb(Random r, double[] p, int maxUlps) => p.Select(x => ulps(x, r.Next(-maxUlps, maxUlps + 1))).ToArray();

        static double U(Random r) => 2 * r.NextDouble() - 1;

        static double[] near_collinear(Random r)
        {
            double ax = U(r), ay = U(r), bx = U(r), by = U(r), t = r.NextDouble();
            return perturb(r, new[] { ax, ay, bx, by, ax + t * (bx - ax), ay + t * (by - ay) }, 4);
        }

        static double[] near_cocircular(Random r)
        {
            double cx = U(r), cy = U(r), rad = 0.5 + 1.5 * r.NextDouble();
            var ang = Enumerable.Range(0, 4).Select(_ => 2 * Math.PI * r.NextDouble()).ToList();
            var p = new List<double>();
            foreach (double a in ang) { p.Add(cx + rad * Math.Cos(a)); p.Add(cy + rad * Math.Sin(a)); }
            return perturb(r, p.ToArray(), 4);
        }

        // multiples 2^k u of one vector: exactly collinear (and cocircular), with inexact differences
        static double[] pow2_degenerate(Random r, int n)
        {
            double ux = U(r), uy = U(r);
            var p = new List<double>();
            for (int k = 0; k < n; ++k) {
                double s = Math.Pow(2, r.Next(-40, 41));
                p.Add(s * ux); p.Add(s * uy);
            }
            return p.ToArray();
        }

        static double[] grid_collinear(Random r)
        {
            int ax = r.Next(-1000, 1000), ay = r.Next(-1000, 1000), dx = r.Next(-20, 21), dy = r.Next(-20, 21);
            int m = r.Next(-50, 50), n = r.Next(-50, 50);
            return new double[] { ax, ay, ax + m * dx, ay + m * dy, ax + n * dx, ay + n * dy };
        }

        static readonly int[,] Circle5 = { { 5, 0 }, { 4, 3 }, { 3, 4 }, { 0, 5 }, { -3, 4 }, { -4, 3 }, { -5, 0 }, { -4, -3 }, { -3, -4 }, { 0, -5 }, { 3, -4 }, { 4, -3 } };

        static double[] grid_cocircular(Random r)
        {
            var idx = Enumerable.Range(0, 12).OrderBy(_ => r.Next()).Take(4).ToList();
            int cx = r.Next(-1000, 1000), cy = r.Next(-1000, 1000), k = r.Next(1, 100);
            return idx.SelectMany(i => new double[] { cx + k * Circle5[i, 0], cy + k * Circle5[i, 1] }).ToArray();
        }

        /// <summary>
        /// The rounded differences are exactly collinear / cocircular, the inputs are not: stage B's value is 0 but
        /// the determinant is not (the tails decide). Orient2d: a = (e1, e2) tiny, b and c = m b on a line through
        /// the origin; InCircle: d = (5 k + e1, e2) next to the circle of radius 5 k through a, b, c.
        /// </summary>
        static double[] rounded_degenerate(Random r, bool circle)
        {
            double e1 = Math.Pow(2, -60 - r.Next(0, 20)) * r.Next(1, 8) * (r.Next(2) * 2 - 1);
            double e2 = r.Next(3) == 0 ? 0 : Math.Pow(2, -60 - r.Next(0, 20)) * r.Next(1, 8) * (r.Next(2) * 2 - 1);
            if (!circle) {
                int px = r.Next(-20, 21), py = r.Next(1, 21), m = r.Next(2, 9) * (r.Next(2) * 2 - 1);
                return new double[] { e1, e2, px, py, m * px, m * py };
            }
            var idx = Enumerable.Range(1, 11).OrderBy(_ => r.Next()).Take(3).ToList();     // not (5, 0)
            int k = r.Next(1, 30);
            var p = idx.SelectMany(i => new double[] { k * Circle5[i, 0], k * Circle5[i, 1] }).ToList();
            p.Add(5 * k + e1); p.Add(e2);
            return p.ToArray();
        }

        // Kettner et al., "Classroom examples of robustness problems in geometric computations": (0.5 + i ulp,
        // 0.5 + j ulp) against the line (12, 12) - (24, 24) / the circle through (23.5, 0.5), (23.5, 23.5), (0.5, 23.5)
        static IEnumerable<double[]> kettner(int kind, int n)
        {
            double u = next(0.5) - 0.5;
            for (int i = 0; i < n; ++i)
                for (int j = 0; j < n; ++j) {
                    double x = 0.5 + i * u, y = 0.5 + j * u;
                    yield return kind == 0 ? new[] { x, y, 12, 12, 24, 24 } : new[] { 23.5, 0.5, 23.5, 23.5, 0.5, 23.5, x, y };
                }
        }

        static double[] scaled(double[] p, double s) => p.Select(x => x * s).ToArray();

        static readonly double[] Scales = { 1, 1e6, 1e-10, 1e-160, 1e-300, 1e150, 1e200, Math.Pow(2, -1040) };

        static IEnumerable<double[]> cases(int kind, int n)
        {
            var r = new Random(4711 + kind);
            bool circle = kind == 1;
            for (int i = 0; i < n; ++i) {
                yield return circle ? near_cocircular(r) : near_collinear(r);
                yield return pow2_degenerate(r, circle ? 4 : 3);
                yield return circle ? grid_cocircular(r) : grid_collinear(r);
                yield return rounded_degenerate(r, circle);
                yield return Enumerable.Range(0, circle ? 8 : 6).Select(_ => U(r)).ToArray();
            }
        }

        // --- tests

        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void Generated_MatchesBigInteger_AtManyScales(int kind)
        {
            foreach (double s in Scales)
                foreach (var p0 in cases(kind, 300)) {
                    var p = scaled(p0, s);
                    int expected = kind == 0 ? orient2d_ref(p) : incircle_ref(p);
                    int got = kind == 0 ? orient2d(p) : incircle(p);
                    Assert.True(expected == got, $"scale {s}: {string.Join(", ", p.Select(x => x.ToString("R")))}: {got}, expected {expected}");
                }
        }

        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void Generated_EqualsHandWrittenPredicates(int kind)
        {
            foreach (double s in Scales)
                foreach (var p0 in cases(kind, 100)) {
                    var p = scaled(p0, s);
                    int hand = kind == 0
                        ? ExactPredicates.Orient2d(new Vector2d(p[0], p[1]), new Vector2d(p[2], p[3]), new Vector2d(p[4], p[5]))
                        : ExactPredicates.InCircle(new Vector2d(p[0], p[1]), new Vector2d(p[2], p[3]), new Vector2d(p[4], p[5]), new Vector2d(p[6], p[7]));
                    Assert.Equal(hand, kind == 0 ? orient2d(p) : incircle(p));
                }
        }

        /// <summary> the filter decides only correctly, also where products underflow (its absolute term) </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void Filter_DecidesOnlyCorrectly(int kind)
        {
            int decided = 0, total = 0;
            // (InCircle's products underflow near 1e-80, Orient2d's near 1e-160)
            var scales = Scales.Concat(new[] { 1e-155, 1e-162, 1e-78, 1e-80, 1e-81 })
                .Concat(Enumerable.Range(258, 24).Select(e => Math.Pow(2, -e)))     // InCircle's products in the subnormal range
                .Concat(Enumerable.Range(515, 24).Select(e => Math.Pow(2, -e)));    // Orient2d's
            foreach (double s in scales)
                foreach (var p0 in cases(kind, 200).Concat(kettner(kind, 60))) {
                    var p = scaled(p0, s);
                    int f = kind == 0 ? GeneratedPredicates.Orient2dFilter(p[0], p[1], p[2], p[3], p[4], p[5])
                                      : GeneratedPredicates.InCircleFilter(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7]);
                    total++;
                    if (f == 0) continue;
                    decided++;
                    Assert.Equal(kind == 0 ? orient2d_ref(p) : incircle_ref(p), f);
                }
            // (most scales overflow or underflow for the degree-4 InCircle; at the others the general cases are decided)
            Assert.True(decided > 1000, $"the filter decided only {decided} of {total}");
        }

        /// <summary> the exact stages without the filter, and stage D alone (without the bounds of B and C) </summary>
        [Theory]
        [InlineData(0, 0)]
        [InlineData(0, 1)]
        [InlineData(1, 0)]
        [InlineData(1, 1)]
        public void ExactStages_MatchBigInteger(int kind, int skip)
        {
            foreach (double s in new[] { 1, 1e6, 1e-10, Math.Pow(2, -90), Math.Pow(2, 90) })
                foreach (var p0 in cases(kind, 300)) {
                    var p = scaled(p0, s);
                    int got = kind == 0 ? GeneratedPredicates.Orient2dExact(p[0], p[1], p[2], p[3], p[4], p[5], skip)
                                        : GeneratedPredicates.InCircleExact(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], skip);
                    Assert.Equal(kind == 0 ? orient2d_ref(p) : incircle_ref(p), got);
                }
        }

        /// <summary>
        /// stages B and C decide most nearly degenerate cases (with inexact differences) on their own, and correctly;
        /// stage D is the exception (silent fall-through to D would only show in the time)
        /// </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void StagesBAndC_DecideMostNearlyDegenerateCases(int kind)
        {
            var r = new Random(77 + kind);
            int byB = 0, byBC = 0, n = 3000;
            for (int i = 0; i < n; ++i) {
                var p = kind == 0 ? near_collinear(r) : near_cocircular(r);
                int expected = kind == 0 ? orient2d_ref(p) : incircle_ref(p);
                for (int skip = 2; skip <= 3; ++skip) {
                    int got = kind == 0 ? GeneratedPredicates.Orient2dExact(p[0], p[1], p[2], p[3], p[4], p[5], skip)
                                        : GeneratedPredicates.InCircleExact(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], skip);
                    if (got == 2) continue;
                    Assert.Equal(expected, got);
                    if (skip == 3) byB++; else byBC++;
                }
            }
            Assert.True(byBC > n * 9 / 10, $"stages B and C decided {byBC} of {n}");
            // (measured: B decides 2313 / 1141 of 3000, including the cases with exact differences; without its bound
            // 618 / 172)
            Assert.True(byB > (kind == 0 ? n / 2 : n / 4) && byB < byBC, $"stage B decided {byB}, B and C {byBC} of {n}");
        }

        /// <summary> inputs at the limits of the expansion range [2^-100, 2^100] and just outside </summary>
        [Fact]
        public void RangeGate_Boundaries()
        {
            double hi = Math.Pow(2, 100), lo = Math.Pow(2, -100);
            double[] edge = { hi, next(hi), prev(hi), lo, prev(lo), next(lo), -hi, -lo };
            var r = new Random(3);
            for (int i = 0; i < 20000; ++i) {
                var p = Enumerable.Range(0, 8).Select(_ => r.Next(3) == 0 ? 0 : edge[r.Next(edge.Length)] * (1 + r.Next(4) * Math.Pow(2, -52))).ToArray();
                Assert.Equal(orient2d_ref(p), orient2d(p));
                Assert.Equal(incircle_ref(p), incircle(p));
            }
        }

        [Fact]
        public void RoundedDifferencesDegenerate_TailsDecide()
        {
            // (b - a) x (c - a) with a = (2^-60, 0), b = (1, 1), c = (2, 2): the rounded differences (1, 1), (2, 2)
            // are collinear, the exact ones are not: -2^-60
            Assert.Equal(-1, GeneratedPredicates.Orient2d(Math.Pow(2, -60), 0, 1, 1, 2, 2));
            Assert.Equal(1, GeneratedPredicates.Orient2d(-Math.Pow(2, -60), 0, 1, 1, 2, 2));
            var r = new Random(5);
            int nonzero = 0;
            for (int i = 0; i < 2000; ++i)
                for (int kind = 0; kind < 2; ++kind) {
                    var p = rounded_degenerate(r, kind == 1);
                    int expected = kind == 0 ? orient2d_ref(p) : incircle_ref(p);
                    if (expected != 0) nonzero++;
                    Assert.Equal(expected, kind == 0 ? orient2d(p) : incircle(p));
                }
            Assert.True(nonzero > 1000);
        }

        /// <summary>
        /// Exact for every frame of Similarity.All() (the transformed coordinates are rounded, so only the exact
        /// frames, scaling by 2^k, must keep the sign of the original)
        /// </summary>
        [Theory]
        [InlineData(0)]
        [InlineData(1)]
        public void Invariance_AllSimilarities(int kind)
        {
            foreach (var sim in Similarity.All())
                foreach (var p0 in cases(kind, 100)) {
                    var p = new double[p0.Length];
                    for (int i = 0; i < p.Length; i += 2) {
                        var q = sim.Apply(new Vector3d(p0[i], p0[i + 1], 0));
                        p[i] = q.x; p[i + 1] = q.y;
                    }
                    int got = kind == 0 ? orient2d(p) : incircle(p);
                    Assert.Equal(kind == 0 ? orient2d_ref(p) : incircle_ref(p), got);
                    if (sim.IsExact)
                        Assert.Equal(kind == 0 ? orient2d(p0) : incircle(p0), got);
                }
        }

        /// <summary>
        /// subnormal partial products times large factors (the absolute term of the filter): the case of
        /// ExactPredicatesTests.Predicates_SubnormalPartialProducts_TimesLargeFactors, and coordinates of independent
        /// magnitudes (2^-1080 to 2^400)
        /// </summary>
        [Fact]
        public void SubnormalPartialProducts_TimesLargeFactors()
        {
            double X = Math.Pow(2, 210), unit = double.Epsilon;
            double[] p = { X, -8.93 * X * X * unit, 0.8, 2 * unit, 0.7, 2 * unit, 0, 0 };
            Assert.Equal(-1, incircle_ref(p));
            Assert.Equal(-1, incircle(p));
            var rnd = new Random(5);
            Func<double> coord = () => (rnd.NextDouble() - 0.5) * Math.Pow(2, rnd.Next(-1080, 400));
            for (int i = 0; i < 100000; ++i) {
                var q = Enumerable.Range(0, 8).Select(_ => coord()).ToArray();
                Assert.Equal(orient2d_ref(q), orient2d(q));
                Assert.Equal(incircle_ref(q), incircle(q));
            }
        }

        /// <summary>
        /// exactly cocircular (multiples 2^k u), where the computed determinant is 2.0-2.2 u times the permanent (the
        /// largest found in 2M random such cases): a filter constant below that decides them wrongly. (Constants
        /// between the attained error and the derived 10 u cannot be told apart by tests; their soundness rests on
        /// the derivation, docs/design/PREDICATE_COMPILER.md.)
        /// </summary>
        [Fact]
        public void Filter_LargeAttainedErrors_StayUndecided()
        {
            double[][] cases = {
                new[] { 6.687284339421992E-11, 1.0223396878834351E-10, 4705.75800924085, 7194.07599593423, 1.0699654943075188E-09, 1.6357435006134961E-09, 2.1912893323417985E-06, 3.35000268925644E-06 },
                new[] { 4805.796537729817, -2558.3521397106124, 1.7902987218386743E-05, -9.530604406113224E-06, 4.475746804596686E-06, -2.382651101528306E-06, 0.0002864477954941879, -0.00015248967049781158 },
                new[] { 1.1189948937943455E-09, 2.2302156624913976E-09, 615.1739485744265, 1226.0740266787234, 20158019.946886808, 40175993.70620841, 38.44837178590166, 76.62962666742021 },
            };
            foreach (var p in cases) {
                Assert.Equal(0, incircle_ref(p));
                Assert.Equal(0, GeneratedPredicates.InCircleFilter(p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7]));
                Assert.Equal(0, incircle(p));
            }
        }

        [Fact]
        public void NonFiniteInput_ThrowsAsHandWritten()
        {
            Assert.Throws<ArgumentException>(() => GeneratedPredicates.Orient2d(double.NaN, 0, 1, 0, 0, 1));
            Assert.Throws<ArgumentException>(() => GeneratedPredicates.Orient2d(double.PositiveInfinity, 0, 1, 0, 0, 1));
            Assert.Throws<ArgumentException>(() => GeneratedPredicates.InCircle(0, 0, 1, 0, 0, 1, double.NaN, 0));
            Assert.Throws<ArgumentException>(() => GeneratedPredicates.InCircle(0, 0, 1, 0, 0, 1, 0, double.NegativeInfinity));
        }
    }
}
